const https = require('https');

async function translateHebrew(text) {
  return new Promise((resolve, reject) => {
    const encoded = encodeURIComponent(text.trim());
    const url = 'https://api.mymemory.net/api/transliterate?q=' + encoded + '&langpair=iw|en';

    https.get(url, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        try {
          const parsed = JSON.parse(data);
          resolve(parsed.responseData?.translatedText || text);
        } catch (e) {
          resolve(text);
        }
      });
    }).on('error', () => resolve(text));
  });
}

function isHebrew(text) {
  if (!text || typeof text !== 'string') return false;
  const hebrewChars = text.match(/\u0590-\u05FF/g);
  return hebrewChars && (hebrewChars.length / text.length) >= 0.2;
}

async function hebrew_translator(args) {
  const { prompt, reply_inEnglish = false, force_rtl = false, force_translate = false } = args;

  // Validate options
  if (force_rtl && reply_inEnglish) {
    return {
      success: false,
      error: 'Options --rtl and --english are incompatible'
    };
  }

  // Check if Hebrew
  const hebrew = isHebrew(prompt) || force_translate;

  if (!hebrew) {
    return {
      success: true,
      is_hebrew: false,
      original: prompt,
      translated: null,
      final_prompt: prompt,
      message: 'Text is not Hebrew, returning as-is'
    };
  }

  // Translate
  const translated = await translateHebrew(prompt);

  // Build response instruction
  let instruction = reply_inEnglish
    ? 'Important! Reply in English only'
    : 'Important! Reply in Hebrew';

  if (force_rtl && !reply_inEnglish) {
    instruction += ' Use RTL formatting with proper Unicode BIDI markers.';
  }

  const finalPrompt = `${translated}. ${instruction}`;

  return {
    success: true,
    is_hebrew: true,
    original: prompt,
    translated: translated,
    final_prompt: finalPrompt,
    response_language: reply_inEnglish ? 'English' : 'Hebrew',
    token_savings_estimate: 'Up to 40% on input tokens'
  };
}

module.exports = { hebrew_translator };
